<script setup>
import {ref} from 'vue';
import {PERMS,SCOPES,MODULES,PRI_KEYS,REPORT_DEF,CORE_ADMINS} from '../../lib/task-domain';
const cfg=defineModel({required:true});defineProps({people:Array,disabled:Boolean});const roleName=ref(''),categoryName=ref(''),ticketCategory=ref(''),admin=ref(''),code=ref(''),message=ref(''),section=ref('modules');
function addRole(){const name=roleName.value.trim();if(!name||cfg.value.roles[name])return;cfg.value.roles[name]={scope:'own'};roleName.value='';}
async function setCode(){if(!code.value)return;const hash=await crypto.subtle.digest('SHA-256',new TextEncoder().encode('LIFE-TM|'+code.value));cfg.value.phone.codeHash=[...new Uint8Array(hash)].map(v=>v.toString(16).padStart(2,'0')).join('');code.value='';message.value='New unlock code prepared. Save Control Panel to apply.';}
</script>
<template><section class="control"><nav><button v-for="name in ['modules','roles','users','masters','tickets','privacy']" :key="name" type="button" :class="{on:section===name}" @click="section=name">{{name}}</button></nav><p role="status">{{message}}</p>
<fieldset :disabled="disabled"><section v-if="section==='modules'"><label v-for="[key,label,help] in MODULES" :key="key"><input v-model="cfg.modules[key]" type="checkbox" :true-value="1" :false-value="0">{{label}} <small>{{help}}</small></label></section>
<section v-else-if="section==='roles'"><div class="scroll"><table><thead><tr><th>Role</th><th>Data scope</th><th v-for="[key,label] in PERMS" :key="key">{{label}}</th></tr></thead><tbody><tr v-for="(rights,name) in cfg.roles" :key="name"><th>{{name}}</th><td><select v-model="rights.scope"><option v-for="[key,label] in SCOPES" :key="key" :value="key">{{label}}</option></select></td><td v-for="[key,label] in PERMS" :key="key"><input v-model="rights[key]" type="checkbox" :true-value="1" :false-value="0" :aria-label="name+' '+label"></td></tr></tbody></table></div><input v-model="roleName" placeholder="New role name"><button type="button" @click="addRole">Add role</button></section>
<section v-else-if="section==='users'"><p>Core admins: {{CORE_ADMINS.join(', ')}}</p><label v-for="person in people.filter(p=>p.login)" :key="person.user">{{person.name}}<select v-model="cfg.userRoles[person.user]"><option :value="undefined">Use designation / default</option><option v-for="(_,role) in cfg.roles" :key="role">{{role}}</option></select></label><h3>Default role</h3><select v-model="cfg.defaultRole"><option v-for="(_,role) in cfg.roles" :key="role">{{role}}</option></select><h3>Designation rules</h3><label v-for="(rule,i) in cfg.desigRules" :key="i"><input v-model="rule[0]" placeholder="Designation"><select v-model="rule[1]"><option v-for="(_,role) in cfg.roles" :key="role">{{role}}</option></select><button type="button" @click="cfg.desigRules.splice(i,1)">Remove</button></label><button type="button" @click="cfg.desigRules.push(['',cfg.defaultRole])">Add designation rule</button><h3>Additional admins</h3><label v-for="(user,i) in cfg.admins" :key="i">{{user}}<button type="button" @click="cfg.admins.splice(i,1)">Remove</button></label><select v-model="admin"><option value="">Choose user</option><option v-for="p in people.filter(p=>p.login)" :key="p.user" :value="p.user">{{p.name}}</option></select><button type="button" @click="admin&&!cfg.admins.includes(admin)&&cfg.admins.push(admin)">Add admin</button></section>
<section v-else-if="section==='masters'"><h3>Task categories</h3><label v-for="(cat,i) in cfg.categories" :key="i"><input v-model="cat.a" type="checkbox" :true-value="1" :false-value="0"><input v-model="cat.n"></label><input v-model="categoryName" placeholder="New category"><button type="button" @click="categoryName.trim()&&(cfg.categories.push({n:categoryName.trim(),a:1}),categoryName='')">Add category</button><h3>Priorities</h3><label v-for="key in PRI_KEYS" :key="key">{{key}}<input v-model="cfg.pri[key].label" placeholder="Label"><input v-model="cfg.pri[key].hint" placeholder="Hint"></label><h3>Reporting types</h3><label v-for="report in REPORT_DEF" :key="report.k"><input v-model="cfg.reports[report.k]" type="checkbox" :true-value="1" :false-value="0">{{report.label}}</label></section>
<section v-else-if="section==='tickets'"><label v-for="(hours,priority) in cfg.sla" :key="priority">{{priority}} SLA hours<input v-model.number="cfg.sla[priority]" type="number" min="1"></label><details v-for="(category,name) in cfg.tCats" :key="name"><summary>{{name}}</summary><label><input v-model="category.a" type="checkbox" :true-value="1" :false-value="0">Enabled</label><label>Default resolver<select v-model="cfg.resolvers[name]"><option value="">Auto-suggest</option><option v-for="p in people.filter(p=>p.login)" :key="p.user" :value="p.user">{{p.name}}</option></select></label><label v-for="(issue,i) in category.issues" :key="i"><input v-model="issue.a" type="checkbox" :true-value="1" :false-value="0"><input v-model="issue.n"></label><button type="button" @click="category.issues.push({n:'New issue',a:1})">Add issue</button></details><input v-model="ticketCategory" placeholder="New ticket category"><button type="button" @click="ticketCategory.trim()&&!cfg.tCats[ticketCategory]&&(cfg.tCats[ticketCategory]={a:1,issues:[{n:'Other',a:1}]},ticketCategory='')">Add category</button></section>
<section v-else><label><input v-model="cfg.phone.mask" type="checkbox" :true-value="1" :false-value="0">Mask mobile numbers</label><label>Unlock duration (minutes)<input v-model.number="cfg.phone.minutes" type="number" min="1"></label><label>New unlock code<input v-model="code" type="password" autocomplete="new-password"></label><button type="button" @click="setCode">Set new code</button><button type="button" @click="cfg.phone.codeHash=''">Remove code</button></section></fieldset></section></template>
<style scoped>fieldset{border:0;padding:0}label{display:flex;gap:10px;align-items:center;padding:7px;flex-wrap:wrap}input,select,button{font:inherit;padding:7px}small{color:#657b6c}nav{display:flex;gap:7px;flex-wrap:wrap}nav .on{background:#175933;color:white}.scroll{overflow:auto}td,th{padding:8px;border-bottom:1px solid #dce6df}h3{margin:18px 0 8px}details{padding:10px;border-bottom:1px solid #dce6df}</style>
